        print(line[:500])

# Also check all types of messages present
print("\n\n--- All message types ---")
for line in lines:
    data = json.loads(line)
    msg_type = data.get('type', '')
    if msg_type == 'message' and 'content' in data:
        content = data['content']
        if isinstance(content, list):
            for item in content:
                if item.get('type') == 'thinking':
                    text = item.get('text', '')
                    if 'col 10' in text.lower() or 'submit' in text.lower():
